-- Master data: align category names, then load the standard catalogue.
-- 1) The Admin portal used to write CAR_MAKE / CAR_BODY_TYPE / TRANSMISSION_TYPE while the apps read MAKE / BODY_TYPE / TRANSMISSION,
--    so items administrators added never reached customers. Rename them (only where the canonical row does not already exist).
UPDATE "MasterDataItem" m SET "category" = 'MAKE' WHERE m."category" = 'CAR_MAKE' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'MAKE' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'MODEL' WHERE m."category" = 'CAR_MODEL' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'MODEL' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'VARIANT' WHERE m."category" = 'CAR_VARIANT' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'VARIANT' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'BODY_TYPE' WHERE m."category" = 'CAR_BODY_TYPE' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'BODY_TYPE' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'TRANSMISSION' WHERE m."category" = 'TRANSMISSION_TYPE' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'TRANSMISSION' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'COLOR' WHERE m."category" = 'CAR_COLOR' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'COLOR' AND x."code" = m."code");
UPDATE "MasterDataItem" m SET "category" = 'COLOR' WHERE m."category" = 'CAR_COLOUR' AND NOT EXISTS (SELECT 1 FROM "MasterDataItem" x WHERE x."category" = 'COLOR' AND x."code" = m."code");
-- 2) Standard catalogue (makes, models, colours, fuel, transmission, ownership, body types, documents). Existing rows are never changed.
ON CONFLICT ("category", "code") DO NOTHING;
